<?php
declare(strict_types=1);
/** Phase 2 feature tests: appointments, catalogue import, SMS fallback, Lead Ads, ad referrals. Included by tests/run.php. */
use CaliChat\Core\{Crypto, Db, Platform, Tenant};
use CaliChat\Services\{Appointments, Automations, Chat, Importers, LeadAds, Meta, Queue, Sms, Store, StoreError, ToolRunner};

echo "\nPhase 2: appointments, catalogue import, SMS, lead ads\n";
$logLines2 = fn(string $file) => is_file(sys_get_temp_dir() . '/' . $file) ? array_map(fn($l) => json_decode($l, true), file(sys_get_temp_dir() . '/' . $file, FILE_IGNORE_NEW_LINES)) : [];
$tzColombo = new DateTimeZone('Asia/Colombo');
$openDate = function (int $minDays = 3) use ($tzColombo) { $d = new DateTime("today +$minDays days", $tzColombo); while ((int)$d->format('N') === 7) $d->modify('+1 day'); return $d->format('Y-m-d'); };
$sunday = function () use ($tzColombo) { $d = new DateTime('today +3 days', $tzColombo); while ((int)$d->format('N') !== 7) $d->modify('+1 day'); return $d->format('Y-m-d'); };
$mkSvc = fn(int $tid, string $name = 'Haircut', int $dur = 30, int $cap = 1) => Db::insert('appt_services', ['tenant_id' => $tid, 'name' => $name, 'duration_min' => $dur, 'price' => 1500, 'capacity' => $cap]);
$errCode = function (callable $f): int { try { $f(); } catch (StoreError $e) { return (int)$e->getCode(); } return 0; };

t('appointments: free slots follow business hours, notice and the past; booking never double-books; cancelling frees the time', function () use ($openDate, $sunday, $mkSvc, $errCode, $tzColombo) {
    $v = mkTenant('Ap'); $tid = $v['tid']; $svc = $mkSvc($tid); $date = $openDate();
    $s = Appointments::slots($tid, $svc, $date); eq($s[0], '09:00'); eq(end($s), '16:30'); eq(count($s), 16, 'Mon-Sat 09:00-17:00 in 30-minute steps by default');
    eq(Appointments::slots($tid, $svc, $sunday()), [], 'closed on Sunday'); eq(Appointments::slots($tid, $svc, (new DateTime('yesterday', $tzColombo))->format('Y-m-d')), [], 'nothing in the past');
    $noon = (new DateTime("$date 12:00:00", $tzColombo))->getTimestamp(); eq(Appointments::slots($tid, $svc, $date, $noon)[0], '13:00', 'one hour of notice');
    eq($errCode(fn() => Appointments::slots($tid, $svc, '2026-13-45')), 422); eq($errCode(fn() => Appointments::slots($tid, $svc, (new DateTime('today +90 days', $tzColombo))->format('Y-m-d'))), 422, 'too far ahead'); eq($errCode(fn() => Appointments::slots($tid, 999999, $date)), 404);
    Tenant::saveSettings($tid, ['hours' => ['days' => [1, 2, 3, 4, 5, 6, 7], 'start' => '10:00', 'end' => '12:00']]); eq(Appointments::slots($tid, $svc, $date), ['10:00', '10:30', '11:00', '11:30'], 'the tenant profile hours are used'); Tenant::saveSettings($tid, ['hours' => ['days' => [1, 2, 3, 4, 5, 6], 'start' => '09:00', 'end' => '17:00']]);
    $a = Appointments::book($tid, $svc, '94770007001', 'Nimal', "$date 10:00", 'manual'); eq($a['status'], 'booked'); ok(!in_array('10:00', Appointments::slots($tid, $svc, $date), true), 'the booked time disappears');
    eq($errCode(fn() => Appointments::book($tid, $svc, '94770007002', 'Other', "$date 10:00")), 409, 'a second booking of the same time is refused'); eq($errCode(fn() => Appointments::book($tid, $svc, '94770007002', 'Other', "$date 10:15")), 409, 'a time that is not on the grid is refused'); eq($errCode(fn() => Appointments::book($tid, $svc, '94770007002', 'Other', "$date 08:00")), 409, 'outside opening hours');
    eq(Appointments::book($tid, $svc, '94770007001', 'Nimal', "$date 10:00")['id'], $a['id'], 'the same booking twice is one booking'); eq($errCode(fn() => Appointments::book($tid, $svc, '12', 'X', "$date 11:00")), 422);
    $b = Appointments::setStatus($tid, (int)$a['id'], 'cancelled'); eq($b['status'], 'cancelled'); ok(in_array('10:00', Appointments::slots($tid, $svc, $date), true), 'cancelling frees the time'); eq($errCode(fn() => Appointments::setStatus($tid, (int)$a['id'], 'cancelled')), 409);
    eq($errCode(fn() => Appointments::setStatus($tid, (int)$a['id'], 'cancelled', '94779999999')), 404, "another customer's phone cannot touch it");
    $cap = $mkSvc($tid, 'Group class', 60, 2); foreach (['94770007011', '94770007012'] as $p) Appointments::book($tid, $cap, $p, 'P', "$date 09:00"); eq($errCode(fn() => Appointments::book($tid, $cap, '94770007013', 'P', "$date 09:00")), 409, 'capacity 2 is respected'); ok(in_array('10:00', Appointments::slots($tid, $cap, $date), true), 'the next hour is still open');
    foreach (['11:00', '11:30', '12:00'] as $t) Appointments::book($tid, $svc, '94770007020', 'Many', "$date $t"); eq($errCode(fn() => Appointments::book($tid, $svc, '94770007020', 'Many', "$date 13:00")), 409, 'a customer may hold three upcoming appointments');
    $other = mkTenant('ApOther'); eq($errCode(fn() => Appointments::slots($other['tid'], $svc, $date)), 404, "another business's service does not exist for you"); eq((int)Db::val("SELECT COUNT(*) FROM appointments WHERE tenant_id=?", [$other['tid']]), 0);
});
t('appointments: the AI lists services, offers free times and books and cancels through the store tools (preview, reply, confirm)', function () use ($mkSvc, $openDate, $errCode) {
    $v = mkTenant('ApAi'); $tid = $v['tid']; Store::seedSample($tid); $svc = $mkSvc($tid, 'Dental check-up', 30); Store::connect($tid); $phone = '94770008001'; $date = $openDate(4);
    foreach (['list_services', 'get_free_slots', 'my_appointments', 'book_appointment', 'cancel_appointment'] as $n) ok(Db::val("SELECT id FROM tools WHERE tenant_id=? AND name=?", [$tid, $n]) !== null, "$n installed");
    $nobody = mkTenant('ApNone'); Store::seedSample($nobody['tid']); Store::connect($nobody['tid']); eq((int)Db::val("SELECT COUNT(*) FROM tools WHERE tenant_id=? AND name='book_appointment'", [$nobody['tid']]), 0, 'businesses without services get no booking tools');
    $c = Chat::contact($tid, 0, 'whatsapp', 'ap1', 'Dil', $phone); $conv = Chat::conversation($tid, null, 'whatsapp', $c, null); $cid = (int)$conv['id']; $say = fn($m) => Chat::addMessage($tid, $cid, 'in', 'customer', $m);
    $tool = fn($n) => Db::one("SELECT * FROM tools WHERE tenant_id=? AND name=?", [$tid, $n]); $run = fn($n, $a) => ToolRunner::run($tool($n), $a, $c, $cid);
    $r = $run('list_services', []); ok($r['ok'] && strpos(json_encode($r['data']), 'Dental check-up') !== false, 'services listed');
    $r = $run('get_free_slots', ['service_id' => $svc, 'date' => $date]); ok($r['ok'] && strpos(json_encode($r['data']), '09:00') !== false, json_encode($r['data'] ?? $r['error']));
    $args = ['service_id' => $svc, 'start' => "$date 09:30", 'customer_name' => 'Dilani']; $say('book me 9:30 please'); $p = $run('book_appointment', $args); ok($p['ok'] && $p['data']['status'] === 'confirmation_required', 'preview first'); eq((int)Db::val("SELECT COUNT(*) FROM appointments WHERE tenant_id=?", [$tid]), 0);
    $say('yes'); $r = $run('book_appointment', $args + ['customer_confirmed' => true]); ok($r['ok'], (string)$r['error']); eq((int)Db::val("SELECT COUNT(*) FROM appointments WHERE tenant_id=? AND source='ai' AND phone=?", [$tid, $phone]), 1); ok(strpos(json_encode($r['data']), '09:30') !== false);
    $r = $run('my_appointments', []); ok($r['ok'] && strpos(json_encode($r['data']), '09:30') !== false, 'own appointments listed'); $id = Db::val("SELECT id FROM appointments WHERE tenant_id=?", [$tid]);
    $say('another customer wants the same time'); $o = Chat::contact($tid, 0, 'whatsapp', 'ap2', 'Other', '94770008002'); $oc = (int)Chat::conversation($tid, null, 'whatsapp', $o, null)['id'];
    $r = ToolRunner::run($tool('cancel_appointment'), ['id' => (string)$id], $o, $oc); ok(!$r['ok'] || ($r['data']['status'] ?? '') === 'confirmation_required', 'preview only'); Chat::addMessage($tid, $oc, 'in', 'customer', 'yes'); $r = ToolRunner::run($tool('cancel_appointment'), ['id' => (string)$id, 'customer_confirmed' => true], $o, $oc); ok(!$r['ok'] && strpos((string)$r['error'], '404') !== false, "someone else's appointment cannot be cancelled"); eq(Db::val("SELECT status FROM appointments WHERE id=?", [$id]), 'booked');
    $say('please cancel'); $run('cancel_appointment', ['id' => (string)$id]); $say('yes cancel'); $r = $run('cancel_appointment', ['id' => (string)$id, 'customer_confirmed' => true]); ok($r['ok'], (string)$r['error']); eq(Db::val("SELECT status FROM appointments WHERE id=?", [$id]), 'cancelled');
    $prompt = \CaliChat\Services\Agent::systemPrompt(Tenant::get($tid), ['name' => 'K', 'business_name' => 'S', 'tone' => 'x', 'languages' => 'English', 'instructions' => ''], ['name' => 'N', 'channel_type' => 'whatsapp'], '', [], '', '', ['book_appointment', 'create_order']); ok(strpos($prompt, 'APPOINTMENTS') !== false && strpos($prompt, 'NEVER invent') !== false, 'appointment guidance in the prompt');
});
t('appointments: confirmation and reminder follow-ups are sent with the service, day and time, once, and dropped when the booking is cancelled', function () use ($mkSvc, $openDate, $waChannel) {
    $v = mkTenant('ApFu'); $tid = $v['tid']; $ch = $waChannel($tid, '8101'); Tenant::saveSettings($tid, ['quiet_start' => '00:00', 'quiet_end' => '00:00']); Automations::installRecommended($tid); $svc = $mkSvc($tid, 'Haircut'); $phone = '94770009001'; $date = $openDate(3);
    $c = Chat::contact($tid, $ch, 'whatsapp', $phone, 'Kamal', $phone); $conv = Chat::conversation($tid, Db::one("SELECT * FROM channels WHERE id=?", [$ch]), 'whatsapp', $c, null); Chat::addMessage($tid, (int)$conv['id'], 'in', 'customer', 'hi');
    $a = Appointments::book($tid, $svc, $phone, 'Kamal', "$date 10:00", 'ai'); $r = Automations::tick(); eq($r['sent'], 1, json_encode($r)); $m = Db::one("SELECT content FROM messages WHERE conversation_id=? AND sender='ai' ORDER BY id DESC LIMIT 1", [$conv['id']])['content'];
    ok(strpos($m, 'Haircut') !== false && strpos($m, '10:00') !== false && strpos($m, 'Kamal') !== false, 'confirmation text: ' . $m);
    eq(Automations::scan(), 0, 'not within the reminder window yet'); Db::q("UPDATE appointments SET start_at = NOW() + INTERVAL 2 HOUR WHERE id=?", [$a['id']]); $n = Automations::scan(); ok($n >= 1, "reminder scheduled ($n)"); eq(Automations::scan(), 0, 'once');
    $r = Automations::tick(); ok($r['sent'] >= 1, json_encode($r)); $m = Db::one("SELECT content FROM messages WHERE conversation_id=? AND sender='ai' ORDER BY id DESC LIMIT 1", [$conv['id']])['content']; ok(strpos($m, 'Reminder') !== false && strpos($m, 'Haircut') !== false, 'reminder text: ' . $m);
    $svc2 = $mkSvc($tid, 'Shave'); $b = Appointments::book($tid, $svc2, $phone, 'Kamal', "$date 14:00", 'ai'); Automations::tick(); Db::q("UPDATE appointments SET start_at = NOW() + INTERVAL 2 HOUR WHERE id=?", [$b['id']]); Automations::scan(); Appointments::setStatus($tid, (int)$b['id'], 'cancelled'); Db::q("UPDATE automation_runs SET due_at=NOW() WHERE tenant_id=?", [$tid]); Automations::tick();
    ok(stripos((string)Db::val("SELECT r.reason FROM automation_runs r JOIN automations a ON a.id=r.automation_id WHERE a.trigger_type='appointment_reminder' AND r.subject_id=? AND a.tenant_id=?", [$b['id'], $tid]), 'no longer booked') !== false, 'a cancelled booking gets no reminder');
});
t('catalogue import: WooCommerce and Shopify products are mapped, bad keys explained, secrets encrypted, owners only', function () {
    $v = mkTenant('Imp'); $tid = $v['tid'];
    eq(Importers::baseUrl('woocommerce', 'http://127.0.0.1:8766'), 'http://127.0.0.1:8766', 'a local test address is allowed here'); eq(Importers::baseUrl('woocommerce', 'ftp://x'), null); eq(Importers::baseUrl('shopify', 'myshop.myshopify.com'), 'https://myshop.myshopify.com'); eq(Importers::baseUrl('shopify', 'evil.example.com'), null);
    $add = fn($type, $cred) => Db::insert('store_sources', ['tenant_id' => $tid, 'type' => $type, 'base_url' => 'http://127.0.0.1:8766', 'credentials' => Crypto::encrypt(json_encode($cred))]);
    $bad = $add('woocommerce', ['key' => 'ck_wrong', 'secret' => 'x']); $r = Importers::sync($tid, $bad); ok(!$r['ok'] && strpos((string)$r['error'], 'refused') !== false, (string)$r['error']); ok(strpos((string)Db::val("SELECT last_status FROM store_sources WHERE id=?", [$bad]), 'Failed') === 0);
    Db::update('store_sources', ['credentials' => Crypto::encrypt(json_encode(['key' => 'ck_test', 'secret' => 'cs_test']))], 'id=?', [$bad]); $r = Importers::sync($tid, $bad); ok($r['ok'] && $r['added'] === 2, json_encode($r));
    $p = Db::one("SELECT * FROM store_products WHERE tenant_id=? AND sku='WC-LIN-1'", [$tid]); ok($p !== null, 'SKU upper-cased'); eq((float)$p['price'], 4500.0); eq((int)$p['stock'], 7); eq($p['variants'], 'S,M,L'); eq($p['colors'], 'White,Sky Blue'); eq($p['category'], 'Shirts'); eq($p['description'], 'Cool & breathable linen.'); eq($p['image_url'], 'https://cdn.example.lk/linen.jpg');
    $t = Db::one("SELECT * FROM store_products WHERE tenant_id=? AND sku='WC-12'", [$tid]); eq((float)$t['price'], 2500.0, 'falls back to the regular price'); eq((int)$t['stock'], 0, 'out of stock stays out of stock');
    Db::update('store_products', ['stock' => 99], "tenant_id=? AND sku='WC-LIN-1'", [$tid]); Importers::sync($tid, $bad); eq((int)Db::val("SELECT stock FROM store_products WHERE tenant_id=? AND sku='WC-LIN-1'", [$tid]), 7, 'a second import updates, it does not duplicate'); eq((int)Db::val("SELECT COUNT(*) FROM store_products WHERE tenant_id=?", [$tid]), 2);
    $sh = $add('shopify', ['token' => 'shpat_test']); $r = Importers::sync($tid, $sh); ok($r['ok'] && $r['added'] === 1, json_encode($r)); $h = Db::one("SELECT * FROM store_products WHERE tenant_id=? AND sku='SH-HOOD-M'", [$tid]); ok($h !== null); eq((int)$h['stock'], 7, 'inventory across variants is summed'); eq($h['variants'], 'M,L'); eq($h['colors'], 'Black');
    Db::update('store_sources', ['credentials' => Crypto::encrypt(json_encode(['token' => 'nope']))], 'id=?', [$sh]); ok(!Importers::sync($tid, $sh)['ok']); $other = mkTenant('ImpOther'); ok(!Importers::sync($other['tid'], $sh)['ok'], "another business cannot run this source");
    eq(Importers::syncAll(), 0, 'sources without auto-sync are left alone'); Db::update('store_sources', ['auto_sync' => 1, 'credentials' => Crypto::encrypt(json_encode(['token' => 'shpat_test'])), 'last_sync_at' => null], 'id=?', [$sh]); ok(Importers::syncAll() >= 1, 'auto-sync runs for sources that asked for it');
    // through the page
    $c = new Http('http://127.0.0.1:8765'); $o = mkTenant('ImpPage'); $c->login($o['email']); $csrf = $c->meta(); $post = fn($d) => $c->req('POST', '/app/store', http_build_query($d + ['_csrf' => $csrf]));
    $post(['act' => 'src_save', 'type' => 'woocommerce', 'base_url' => 'http://127.0.0.1:8766', 'key' => 'ck_test', 'secret' => 'cs_test']); $row = Db::one("SELECT * FROM store_sources WHERE tenant_id=?", [$o['tid']]); ok($row !== null); ok(strpos((string)$row['credentials'], 'ck_test') === false && strpos((string)$row['credentials'], 'cs_test') === false, 'keys are stored encrypted');
    $post(['act' => 'src_sync', 'id' => $row['id']]); ok((int)Db::val("SELECT COUNT(*) FROM store_products WHERE tenant_id=?", [$o['tid']]) === 2, 'import from the page'); ok(strpos($c->req('GET', '/app/store')['body'], 'ck_test') === false, 'the page never shows saved keys');
    $s = mkTenant('ImpStaff', 'agent'); Db::update('users', ['tenant_id' => $o['tid']], 'id=?', [$s['uid']]); $sc = new Http('http://127.0.0.1:8765'); $sc->login($s['email']); $sc->req('POST', '/app/store', http_build_query(['_csrf' => $sc->meta(), 'act' => 'src_delete', 'id' => $row['id']])); ok(Db::val("SELECT id FROM store_sources WHERE id=?", [$row['id']]) !== null, 'staff cannot remove sources');
});
t('SMS fallback: configurable provider, secrets encrypted, failures explained; used only when WhatsApp cannot reach the customer and consent allows', function () use ($waChannel, $logLines2) {
    @unlink(sys_get_temp_dir() . '/cc_sms_stub.log'); $v = mkTenant('Sms'); $tid = $v['tid']; Store::seedSample($tid);
    ok(!Sms::enabled($tid)); ok(!Sms::send($tid, '94770001111', 'x')['ok'], 'not set up'); ok(!Sms::urlOk('ftp://x.example') && !Sms::urlOk('javascript:alert(1)'));
    Tenant::saveSettings($tid, ['sms_url' => 'http://127.0.0.1:8766/sms/send?to={to}&text={message}', 'sms_method' => 'GET']); ok(Sms::send($tid, '+94 77 000 1111', 'Hello & welcome 100%')['ok']); $l = $logLines2('cc_sms_stub.log'); eq($l[0]['q']['to'], '94770001111'); eq($l[0]['q']['text'], 'Hello & welcome 100%', 'the message is URL-encoded');
    Tenant::saveSettings($tid, ['sms_url' => 'http://127.0.0.1:8766/sms/send', 'sms_method' => 'POST', 'sms_body' => '{"to":"{to}","message":"{message}"}', 'sms_header' => 'X-Api-Key', 'sms_secret' => Crypto::encrypt('sekret-123')]); ok(Sms::send($tid, '94770001111', "Say \"hi\"\nසුභ දවසක්")['ok']); $l = $logLines2('cc_sms_stub.log'); $j = json_decode($l[1]['raw'], true); eq($j['to'], '94770001111'); eq($j['message'], "Say \"hi\"\nසුභ දවසක්", 'JSON body is escaped and Unicode survives'); eq($l[1]['auth'], 'sekret-123'); ok(stripos($l[1]['ct'], 'json') !== false);
    Tenant::saveSettings($tid, ['sms_url' => 'http://127.0.0.1:8766/sms/fail']); $r = Sms::send($tid, '94770001111', 'x'); ok(!$r['ok'] && strpos((string)$r['error'], '500') !== false, (string)$r['error']);
    Tenant::saveSettings($tid, ['sms_url' => 'http://127.0.0.1:8766/sms/send', 'quiet_start' => '00:00', 'quiet_end' => '00:00']); Automations::installRecommended($tid); @unlink(sys_get_temp_dir() . '/cc_sms_stub.log');
    $ch = $waChannel($tid, '8201'); $phone = '94770002222'; $c = Chat::contact($tid, $ch, 'whatsapp', $phone, 'Nuwan', $phone); $conv = Chat::conversation($tid, Db::one("SELECT * FROM channels WHERE id=?", [$ch]), 'whatsapp', $c, null); Chat::addMessage($tid, (int)$conv['id'], 'in', 'customer', 'hi'); Db::q("UPDATE conversations SET last_customer_at = NOW() - INTERVAL 3 DAY WHERE id=?", [$conv['id']]);
    $ship = function () use ($tid, $phone) { $o = Store::createOrder($tid, ['phone' => $phone, 'customer_name' => 'Nuwan', 'items' => 'AC-503:-:1:Black', 'delivery_city' => 'Colombo', 'delivery_address' => 'x'], 'manual'); $o = Store::setStatus($tid, $o, 'packed'); return Store::setStatus($tid, $o, 'shipped', ['courier' => 'Pronto', 'tracking' => 'PR1']); };
    $run = fn($o, $trig) => Db::one("SELECT r.* FROM automation_runs r JOIN automations a ON a.id=r.automation_id WHERE a.trigger_type=? AND r.subject_id=? AND a.tenant_id=?", [$trig, $o['id'], $tid]);
    $o = $ship(); Automations::tick(); eq($run($o, 'order_shipped')['status'], 'skipped', 'SMS is off by default for each follow-up'); Db::update('automations', ['sms_fallback' => 1], 'tenant_id=?', [$tid]);
    $o2 = $ship(); Automations::tick(); $r = $run($o2, 'order_shipped'); eq($r['status'], 'sent', (string)$r['reason']); ok(strpos((string)$r['reason'], 'SMS') !== false); $l = $logLines2('cc_sms_stub.log'); ok(count($l) >= 1 && strpos($l[count($l) - 1]['raw'], 'PR1') !== false && strpos($l[count($l) - 1]['raw'], $phone) !== false, 'the SMS carries the tracking number');
    Db::update('automations', ['delay_minutes' => 0], 'tenant_id=? AND trigger_type=?', [$tid, 'review_request']); $d = Store::setStatus($tid, Store::setStatus($tid, $o2, 'delivered'), 'delivered'); $rr = $run($o2, 'review_request'); Automations::tick(); eq(Db::val("SELECT status FROM automation_runs WHERE id=?", [$rr['id']]), 'skipped'); ok(strpos((string)Db::val("SELECT reason FROM automation_runs WHERE id=?", [$rr['id']]), 'consent') !== false, 'promotions by SMS need opt-in as well');
    Tenant::saveSettings($tid, ['sms_url' => 'http://127.0.0.1:8766/sms/fail']); $o3 = $ship(); Automations::tick(); eq($run($o3, 'order_shipped')['status'], 'failed', 'a provider error is reported, not hidden');
    $lonely = '94770003333'; Tenant::saveSettings($tid, ['sms_url' => 'http://127.0.0.1:8766/sms/send']); $o4 = Store::createOrder($tid, ['phone' => $lonely, 'customer_name' => 'New', 'items' => 'AC-503:-:1:Black', 'delivery_city' => 'Colombo', 'delivery_address' => 'x'], 'manual'); $o4 = Store::setStatus($tid, Store::setStatus($tid, $o4, 'packed'), 'shipped', ['courier' => 'X', 'tracking' => 'LN9']); Automations::tick(); eq($run($o4, 'order_shipped')['status'], 'sent', 'a customer who never chatted on WhatsApp can still be reached by SMS');
});
t('lead ads: a signed leadgen webhook creates the lead once, with phone and answers, for the right business, and can trigger a welcome', function () use ($waChannel, $logLines2) {
    Platform::set('meta_app_id', '12345'); Platform::set('meta_app_secret', 'platform-secret');
    $v = mkTenant('Lead'); $tid = $v['tid']; Store::seedSample($tid); Tenant::saveSettings($tid, ['quiet_start' => '00:00', 'quiet_end' => '00:00']);
    Db::insert('channels', ['tenant_id' => $tid, 'type' => 'messenger', 'name' => 'Page', 'external_id' => '7771', 'access_token' => Crypto::encrypt('PAGE_TOKEN_7771'), 'verify_token' => 'v', 'channel_key' => rand_key(10), 'managed' => 1]);
    $wa = $waChannel($tid, '8301'); Automations::installRecommended($tid); Db::insert('wa_templates', ['tenant_id' => $tid, 'channel_id' => $wa, 'name' => 'lead_welcome', 'language' => 'en', 'category' => 'utility', 'body' => 'Hi {name}, thanks for your interest in {interest}. {shop} will contact you shortly. Reply here if you have any questions.', 'status' => 'approved']);
    Db::update('automations', ['template_id' => Db::val("SELECT id FROM wa_templates WHERE tenant_id=? AND name='lead_welcome'", [$tid])], "tenant_id=? AND trigger_type='lead_created'", [$tid]); @unlink(sys_get_temp_dir() . '/cc_graph_stub.log');
    $payload = ['object' => 'page', 'entry' => [['id' => '7771', 'time' => time(), 'changes' => [['field' => 'leadgen', 'value' => ['leadgen_id' => '1234567890', 'page_id' => '7771', 'form_id' => '55', 'ad_id' => '66']]]]]];
    $post = function ($p, $secret = 'platform-secret') { $raw = json_encode($p); return $GLOBALS['h']->req('POST', '/webhook/meta', $raw, ['Content-Type: application/json', 'X-Hub-Signature-256: sha256=' . hash_hmac('sha256', $raw, $secret)]); };
    eq($post($payload, 'wrong')['code'], 401, 'bad signature'); eq($post($payload)['code'], 200);
    $l = Db::one("SELECT * FROM crm_leads WHERE tenant_id=?", [$tid]); ok($l !== null, 'lead created'); eq($l['name'], 'Sunil Silva'); eq($l['phone'], '94777654321', '+94 77 765 4321 normalised'); eq($l['email'], 'sunil@example.lk'); eq($l['interest'], 'how many uniforms?: 50 school uniforms'); eq($l['source'], 'ad_form'); eq($l['external_ref'], 'fb:1234567890');
    $post($payload); eq((int)Db::val("SELECT COUNT(*) FROM crm_leads WHERE tenant_id=?", [$tid]), 1, 'Meta retries do not duplicate it'); ok((int)Db::val("SELECT COUNT(*) FROM alerts WHERE tenant_id=? AND type='ad_lead'", [$tid]) === 1, 'team told');
    $rq = array_values(array_filter($logLines2('cc_graph_stub.log'), fn($x) => preg_match('#^/1234567890$#', $x['p']))); ok(count($rq) >= 1 && $rq[0]['auth'] === 'Bearer PAGE_TOKEN_7771', 'read with the Page token');
    $r = Automations::tick(); ok($r['sent'] >= 1, json_encode($r)); $sent = array_values(array_filter($logLines2('cc_graph_stub.log'), fn($x) => $x['p'] === '/8301/messages')); eq(count($sent), 1); eq($sent[0]['j']['type'], 'template', 'a new person can only be reached with a template'); eq($sent[0]['j']['to'], '94777654321'); eq(array_column($sent[0]['j']['template']['components'][0]['parameters'], 'text')[0], 'Sunil Silva');
    eq(Db::val("SELECT consent_status FROM contacts WHERE tenant_id=? AND external_id='94777654321'", [$tid]), 'opted_in', 'filling the form counts as consent'); eq(Db::val("SELECT consent_source FROM contacts WHERE tenant_id=? AND external_id='94777654321'", [$tid]), 'lead_ad_form');
    $before = (int)Db::val("SELECT COUNT(*) FROM crm_leads"); $payload['entry'][0]['changes'][0]['value'] = ['leadgen_id' => '999', 'page_id' => '404404']; $post($payload); eq((int)Db::val("SELECT COUNT(*) FROM crm_leads"), $before, 'a page nobody connected is ignored');
    eq(LeadAds::phone('0771234567'), '94771234567'); eq(LeadAds::phone('771234567'), '94771234567'); eq(LeadAds::phone('+94 (77) 123-4567'), '94771234567');
});
t('ad attribution: click-to-WhatsApp referrals are kept with the first message and attached to the contact once', function () use ($waChannel) {
    $v = mkTenant('Ref'); $tid = $v['tid']; $ch = $waChannel($tid, '8401'); $channel = Db::one("SELECT * FROM channels WHERE id=?", [$ch]);
    $ev = Meta::parse($channel, ['entry' => [['changes' => [['value' => ['metadata' => ['phone_number_id' => '8401'], 'messages' => [['from' => '94770004444', 'id' => 'r1', 'type' => 'text', 'text' => ['body' => 'Is this still available?'], 'referral' => ['source_url' => 'https://fb.me/ad123', 'source_type' => 'ad', 'source_id' => '123', 'headline' => 'School uniforms 20% off', 'body' => 'x', 'ctwa_clid' => 'abc', 'junk' => 'dropped']]]]]]]]]);
    eq($ev[0]['referral']['headline'], 'School uniforms 20% off'); ok(!isset($ev[0]['referral']['junk']), 'only known fields are kept'); ok(Queue::enqueue($channel, $ev[0])); ok(strpos((string)Db::val("SELECT referral FROM inbound_events WHERE tenant_id=? AND provider_id='r1'", [$tid]), 'School uniforms') !== false);
    $c = Chat::contact($tid, $ch, 'whatsapp', '94770004444', 'Kasun', '94770004444'); $c = Chat::applyReferral($c, (string)Db::val("SELECT referral FROM inbound_events WHERE provider_id='r1' AND tenant_id=?", [$tid])); eq($c['acquisition_source'], 'click_to_whatsapp'); eq($c['acquisition_detail'], 'School uniforms 20% off');
    $c2 = Chat::applyReferral($c, json_encode(['headline' => 'Another ad'])); eq($c2['acquisition_detail'], 'School uniforms 20% off', 'the first ad keeps the credit'); eq(Chat::applyReferral($c, 'not json')['acquisition_source'], 'click_to_whatsapp');
});
